#!/bin/bash
# (A) tuned ortho sheets -> Hunyuan MV -> ortho colouring. BLOCKED 2026-11-21: fal balance exhausted. Cost when run: 3x$0.039 + 3x$0.375 = ~$1.24
set -e; cd "$(dirname "$0")"; . .venv/bin/activate
COM="Match the photo EXACTLY in shape, proportions, number of parts and colours; do not stylise, simplify, beautify or add anything. Draw ONLY the main object: no props, furniture, pots, benches, ground, walls or base plates. Colours must be sampled from the photo."
python ortho_gen.py windmill "stone tower windmill" --tag _t --with-photo --extra "$COM Specifics: cylindrical buff-grey limestone tower (about #A89F8C) whose height is about 1.3x its diameter; the lower half is an open arcade of arches on square stone piers with sky visible through the arches; a moulded band between arcade and upper drum; one small dark window on the upper drum; a shallow dark slate-grey lead dome cap. Four WHITE open-lattice sails in an X, each sail about as long as the tower is tall, attached to a hub on the front of the cap. In the TOP plan the tower is a solid filled circle (the grey dome) and the sails are ONE thin straight horizontal bar crossing in front of it; draw no circle outlines, rings or turntables." &
python ortho_gen.py cottage "thatched cottage" --tag _t --with-photo --extra "$COM Specifics: a LONG, LOW Danish thatched cottage. Building length is about 3x its depth. White-painted concrete block walls that are low (wall height about half the roof height). Thick pale grey-green mossy thatched roof with a long, nearly flat ridge running about 75% of the length, rounded hipped ends and a deep overhang over the walls. Two arched thatch eyebrows on the front eave: one over a red arched door left of centre and one over a red multi-pane window right of centre. One dark brick chimney on the ridge near the middle. Side view: narrow hipped end, depth about one third of the front width. Top plan: a long rounded rectangle with the ridge line." &
python ortho_gen.py bonsai "bonsai tree" --tag _t --with-photo --extra "$COM Specifics: a juniper bonsai with a WIDE, flat UMBRELLA-shaped canopy about 2x as wide as it is tall, with a slightly ragged flat underside and wispy edges, made of bright yellow-green needle foliage (about #6FB83A, darker green in the gaps). A slender orange-brown trunk with a gentle S-curve that forks into a Y just below the canopy; the trunk is clearly visible below the canopy for about one third of the total height. A shallow OVAL glossy OXBLOOD-RED pot (about #7A2418) whose width is about 0.55 of the canopy width, filled with dark brown soil. No stand, table or label." &
wait
# then (after visually checking the sheets): ortho_hunyuan.py NAME _t ; ortho_paint.py NAME _t ; tone_to_ref.py ; gallery -> out/ortho_tuned_gallery.png
